import type { Config } from './createConfig';
import { PUBLIC_SELECTED_CONFIG } from '$env/static/public';
import { defaultConfig } from './items/default';
import { stagingConfig } from './items/staging';

export const configs: Record<string, Config> = {
	default: defaultConfig,
	staging: stagingConfig
};

export const getConfig = () => {
	return configs[PUBLIC_SELECTED_CONFIG || 'default'];
};

export const config = getConfig();

import type { PayloadTypes } from '$lib/payload-types';
import { defaultConfig } from './items/default';

export type Config = typeof defaultConfig & {
	localization: {
		urls: Record<PayloadTypes.Config['locale'], string[]>;
	};
};

export const createConfig = (config: Partial<Config> & Record<string, unknown>): Config => {
	return { ...defaultConfig, ...config };
};

export const defaultConfig = {
  blockGoogleIndexing: true,
  urls: {
    default: {
      nl: 'http://localhost:4000',
      de: 'http://localhost:4000',
    },
    internal: 'http://localhost:4000',
    cdn: undefined as string | undefined
  },
  sentry: {
    enabled: false,
    environment: 'development',
    dsn: undefined as string | undefined, // set via env in production
  },
  localization: {
    urls: {
      nl: ['http://app-nl.localhost:3000'],
      de: ['http://app-de.localhost:3000']
    }
  },
  mapbox: {
    accessToken: 'YOUR_MAPBOX_PUBLIC_TOKEN',
  },
  cache: {
    enabled: true,
    ttl: 15 * 1000 // 15 seconds
  }
};

import type { Config } from '../createConfig';
import { defaultConfig } from './default';

export const stagingConfig: Config = {
  ...defaultConfig,
  blockGoogleIndexing: true,
  urls: {
    default: {
      nl: 'https://preview.example-nl.com',
      de: 'https://preview.example-de.com'
    },
    internal: 'http://backend:4000',
    cdn: 'https://cdn.example.com'
  },
  sentry: {
    ...defaultConfig.sentry,
    enabled: true,
    environment: 'staging'
  },
  localization: {
    urls: {
      nl: ['https://preview.example-nl.com'],
      de: ['https://preview.example-de.com']
    }
  },
  cache: {
    ...defaultConfig.cache,
    enabled: true
  }
};

import { PUBLIC_API_BASE } from '$env/static/public';

export function createPayloadClient({ baseUrl, token }: { baseUrl?: string; token?: string }) {
  const apiBase = baseUrl || PUBLIC_API_BASE || 'http://localhost:4000';

  return {
    request: async (args: any) => {
      const url = args.url || `${apiBase}${args.path}`;
      const options: RequestInit = {
        method: args.method || 'GET',
        headers: {
          'Content-Type': 'application/json',
          ...args.headers,
        },
        body: args.body ? JSON.stringify(args.body) : undefined,
        credentials: 'include',
      };

      if (token) {
        options.headers = {
          ...options.headers,
          Authorization: `Bearer ${token}`,
        };
      }

      const response = await fetch(url, options);

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return response.json();
    },
  };
}

